def compute(vars):
    leased = vars["v1"]
    total = vars["v2"]

    if total == 0:
        return None

    ratio = leased / total
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "leased_facilities": leased,
            "total_facilities": total,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
